INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51511, 'Lamentations 3:34', 'Lamentations', 3, 34, 'کله چې په مُلک کښې ټول قېديان د پښو لاندې چخڼى کړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_34.mp3', '', 1761754199, 1761754199),
(51512, 'Lamentations 3:35', 'Lamentations', 3, 35, 'او کله چې يو انسان د خُدائ تعالىٰ په وړاندې د بل چا حق په زور وهى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_35.mp3', '', 1761754199, 1761754199),
(51513, 'Lamentations 3:36', 'Lamentations', 3, 36, 'کله چې يو سړے په عدالت کښې څوک د اِنصاف نه محروموى، ولې مالِک داسې ظلم نۀ ګورى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_36.mp3', '', 1761754199, 1761754199),
(51514, 'Lamentations 3:37', 'Lamentations', 3, 37, 'څوک په خپل حکم څۀ کار کولے شى ترڅو چې مالِک په خپله د هغې حکم نۀ وى کړے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_37.mp3', '', 1761754199, 1761754199),
(51515, 'Lamentations 3:38', 'Lamentations', 3, 38, 'ولې د خُدائ تعالىٰ د خوا نه ښۀ او بد دواړه نۀ راځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_38.mp3', '', 1761754199, 1761754199),
(51516, 'Lamentations 3:39', 'Lamentations', 3, 39, 'نو بيا ژوندے انسان ولې شکايت کوى کله چې ورته د خپلو ګناهونو سزا مِلاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_39.mp3', '', 1761754199, 1761754199),
(51517, 'Lamentations 3:40', 'Lamentations', 3, 40, 'راځئ چې مونږ خپلې طريقې وآزمايو او مالِک خُدائ ته واپس راوګرځُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_40.mp3', '', 1761754199, 1761754199),
(51518, 'Lamentations 3:41', 'Lamentations', 3, 41, 'راځئ چې په اخلاص خپل لاسونه پورته کړُو او آسمانى خُدائ پاک ته داسې ووايو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_41.mp3', '', 1761754199, 1761754199),
(51519, 'Lamentations 3:42', 'Lamentations', 3, 42, '”مونږ ګناه او سرکشى وکړه او تا مونږ معاف کړى نۀ يُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_42.mp3', '', 1761754199, 1761754199),
(51520, 'Lamentations 3:43', 'Lamentations', 3, 43, 'تا خپلې د قهر جامې واغوستلې او مونږ پسې شوې او په بې‌رحمۍ سره دې مونږ مړۀ کړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_43.mp3', '', 1761754199, 1761754199),
(51521, 'Lamentations 3:44', 'Lamentations', 3, 44, 'تا خپل ځان په وريځ کښې ونغښتلو ترڅو هيڅ دُعا هم تا ته در ونۀ رسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_44.mp3', '', 1761754199, 1761754199),
(51522, 'Lamentations 3:45', 'Lamentations', 3, 45, 'تا مونږ پليت کړُو او د قومونو په مينځ کښې دې رانه د ګند ډېرے جوړ کړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_45.mp3', '', 1761754199, 1761754199),
(51523, 'Lamentations 3:46', 'Lamentations', 3, 46, 'زمونږ ټولو دشمنانو زمونږ خلاف خپلې خولې وازې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_46.mp3', '', 1761754199, 1761754199),
(51524, 'Lamentations 3:47', 'Lamentations', 3, 47, 'يرې واخستُو او په کنده کښې وغورزېدُو. تباهى او بربادى راباندې راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_47.mp3', '', 1761754199, 1761754199),
(51525, 'Lamentations 3:48', 'Lamentations', 3, 48, 'زما د خلقو د تباهۍ په وجه زما د سترګو نه د اوښکو سيندونه بهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_48.mp3', '', 1761754199, 1761754199),
(51526, 'Lamentations 3:49', 'Lamentations', 3, 49, 'زما سترګو نه به اوښکې جارى وى بې له آرام کولو نه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_49.mp3', '', 1761754199, 1761754199),
(51527, 'Lamentations 3:50', 'Lamentations', 3, 50, 'ترڅو چې مالِک خُدائ پاس د آسمان نه نظر واچوى او دا حال وګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_50.mp3', '', 1761754199, 1761754199),
(51528, 'Lamentations 3:51', 'Lamentations', 3, 51, 'چې کله زۀ په ښار کښې د ټولو ښځو حالت ګورم نو زما زړۀ غمژن شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_51.mp3', '', 1761754199, 1761754199),
(51529, 'Lamentations 3:52', 'Lamentations', 3, 52, 'هغوئ څوک چې هيڅ بې‌هيڅه زما دشمنان وُو هغوئ لکه د مرغۍ په شان زۀ وويشتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_52.mp3', '', 1761754199, 1761754199),
(51530, 'Lamentations 3:53', 'Lamentations', 3, 53, 'هغوئ زۀ ژوندے په کنده کښې ورواچولم او په ما يې کاڼى راوويشتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_53.mp3', '', 1761754199, 1761754199),
(51531, 'Lamentations 3:54', 'Lamentations', 3, 54, 'اوبۀ زما تر سره راورسېدلې او وئيل مې چې ډوبېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_54.mp3', '', 1761754199, 1761754199),
(51532, 'Lamentations 3:55', 'Lamentations', 3, 55, 'اے مالِکه خُدايه، ما د کندې د بېخ نه ستا په نامه مِنت زارى وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_55.mp3', '', 1761754199, 1761754199),
(51533, 'Lamentations 3:56', 'Lamentations', 3, 56, 'تا زما خواست اورېدلے دے، خپل غوږونه مۀ بندوه، د مدد دپاره زما آواز واوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_56.mp3', '', 1761754199, 1761754199),
(51534, 'Lamentations 3:57', 'Lamentations', 3, 57, 'تۀ ما ته رانزدې شوې کله چې ما درته آواز وکړو، تا ما ته وفرمائيل چې يرېږه مه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_57.mp3', '', 1761754199, 1761754199),
(51535, 'Lamentations 3:58', 'Lamentations', 3, 58, 'اے مالِکه، تا زما مسئله راوچته کړه او تا زما ژوند بچ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_58.mp3', '', 1761754199, 1761754199),
(51536, 'Lamentations 3:59', 'Lamentations', 3, 59, 'اے مالِکه خُدايه، کوم بد چې ما سره وشُو تا هغه وليدل، زما د مسئلې اِنصاف وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_59.mp3', '', 1761754199, 1761754199),
(51537, 'Lamentations 3:60', 'Lamentations', 3, 60, 'تا د هغوئ د انتقام ټول اور وليدو، د هغوئ ټولې منصوبې زما خلاف دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_60.mp3', '', 1761754199, 1761754199),
(51538, 'Lamentations 3:61', 'Lamentations', 3, 61, 'اے مالِکه خُدايه، تا د هغوئ ټول پيغورونه واورېدل، د هغوئ ټولې منصوبې چې زما خلاف دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_61.mp3', '', 1761754199, 1761754199),
(51539, 'Lamentations 3:62', 'Lamentations', 3, 62, 'زما مخالفين ټوله ورځ زما خلاف پس پس او ګنګوسى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_62.mp3', '', 1761754199, 1761754199),
(51540, 'Lamentations 3:63', 'Lamentations', 3, 63, 'هغوئ ته وګوره، سحر نه تر ماښامه پورې، زۀ د هغوئ د پيغورونو په سندرو کښې نمونه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_63.mp3', '', 1761754199, 1761754199),
(51541, 'Lamentations 3:64', 'Lamentations', 3, 64, 'اے مالِکه خُدايه، هغوئ ته بدله ورکړه، هغوئ ته د خپل عمل په مطابق بدله ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_64.mp3', '', 1761754199, 1761754199),
(51542, 'Lamentations 3:65', 'Lamentations', 3, 65, 'هغوئ په زړونو غمژن کړه او ستا لعنت دې په هغوئ باندې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_65.mp3', '', 1761754199, 1761754199),
(51543, 'Lamentations 3:66', 'Lamentations', 3, 66, 'هغوئ په خپله غصه کښې راونيسه، مالِکه خُدايه، د زمکې د مخ نه يې جارُو کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations3_verse_66.mp3', '', 1761754199, 1761754199),
(51544, 'Ezekiel 1:1', 'Ezekiel', 1, 1, 'د دېرشم کال د څلورمې میاشتې په پنځمه ورځ زه حزقیال کاهن د بوزي زوی د جلاوطنه یهودیانو سره د خابور د سیند په غاړه اوسېدم. ناڅاپه اسمان خلاص شو او ما د خدای رویاګانې ولیدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_1.mp3', '', 1761754199, 1761754199),
(51545, 'Ezekiel 1:2', 'Ezekiel', 1, 2, 'دا پنځم کال ؤ چې د یهودا پاچا یهویاکین د اسیر په توګه بابل ته بېول شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_2.mp3', '', 1761754199, 1761754199),
(51546, 'Ezekiel 1:3', 'Ezekiel', 1, 3, 'هلته په بابل کې د خابور د سیند په غاړه ما واورېدل چې څښتن زما سره خبرې کوي او د هغه د حضور زور مې په خپل بدن کې احساس کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_3.mp3', '', 1761754199, 1761754199),
(51547, 'Ezekiel 1:4', 'Ezekiel', 1, 4, 'ما پورته وکتل او ومې لیدل چې د شمال له خوا یو توفان راروان دی. د هغه په مخکې یوه لویه ورېځ روانه وه، برېښنا پړکېدله او د هغې شاوخوا ته اسمان ځلېده. د برېښنا په منځ کې د برنجو په شان یو شی ځلېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_4.mp3', '', 1761754199, 1761754199),
(51548, 'Ezekiel 1:5', 'Ezekiel', 1, 5, 'د توفان په منځ کې ما د انسان په شان څلور ژوندي مخلوقات ولیدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_5.mp3', '', 1761754199, 1761754199),
(51549, 'Ezekiel 1:6', 'Ezekiel', 1, 6, 'خو هغوی هر یو څلور مخونه او څلور وزرونه لرل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_6.mp3', '', 1761754199, 1761754199),
(51550, 'Ezekiel 1:7', 'Ezekiel', 1, 7, 'د هغوی پښې نېغې وې او د خوسي په شان سومان یې لرل. هغه لکه د صیقل شوي برنجو په شان ځلېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_7.mp3', '', 1761754199, 1761754199),
(51551, 'Ezekiel 1:8', 'Ezekiel', 1, 8, 'برسېره پر‌دې چې هغوی څلور مخونه او څلور وزرونه لرل، هغوی د هر وزر لاندې لاسونه هم لرل چې د انسان د لاسونو په شان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_8.mp3', '', 1761754199, 1761754199),
(51552, 'Ezekiel 1:9', 'Ezekiel', 1, 9, 'د هغو ژوندیو مخلوقاتو وزرونه یو له بله سره لګېدل او بې له دې چې راتاو شي هغوی به مخامخ تلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_9.mp3', '', 1761754199, 1761754199),
(51553, 'Ezekiel 1:10', 'Ezekiel', 1, 10, 'د هر یو ژوندي مخلوق څلورو مخونو فرق درلود: مخامخ یې د انسان مخ ؤ، ښي خواته یې د زمري مخ ؤ، چپ خواته یې د غویي مخ ؤ او شاته یې د عقاب مخ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_10.mp3', '', 1761754199, 1761754199),
(51554, 'Ezekiel 1:11', 'Ezekiel', 1, 11, 'د هر ژوندي مخلوق دوه وزرونه پورته خواته خپاره وو او د هغوی د وزرونو څوکې د هغه بل مخلوق سره لګېدلې چې په خوا کې یې ؤ. دوه نورو وزرونو یې د هغوی بدنونه پټول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_11.mp3', '', 1761754199, 1761754199),
(51555, 'Ezekiel 1:12', 'Ezekiel', 1, 12, 'هغوی به مخامخ روان وو او بې له دې چې راتاو شي چېرته به یې چې زړه غوښتل، هلته به تلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_12.mp3', '', 1761754199, 1761754199),
(51556, 'Ezekiel 1:13', 'Ezekiel', 1, 13, 'د ژوندي مخلوقاتو شکل د بلو سکارو یا بلېدونکو څراغونو په شان ؤ او اور د دوی په منځ کې د حرکت په حال کې ؤ. هغه اور ځلېدونکی ؤ او برېښنا به ورڅخه پړکېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_13.mp3', '', 1761754199, 1761754199),
(51557, 'Ezekiel 1:14', 'Ezekiel', 1, 14, 'دا مخلوقات به د برېښنا په شان چټک تلل او راتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_14.mp3', '', 1761754199, 1761754199),
(51558, 'Ezekiel 1:15', 'Ezekiel', 1, 15, 'په داسې حال کې چې ما دې څلورو مخلوقاتو ته کتل، نو څلور ارابې مې ولیدلې چې په ځمکه باندې لګېدلې او د هغوی هر یو په خوا کې یوه یوه ارابه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_15.mp3', '', 1761754199, 1761754199),
(51559, 'Ezekiel 1:16', 'Ezekiel', 1, 16, 'څلور واړه ارابې یوشان وې، هره یوه یې لکه د یوې قیمتي تیږې په شان ځلېدله او د هرې ارابې په منځ کې یوه بله ارابه هم وه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_16.mp3', '', 1761754199, 1761754199),
(51560, 'Ezekiel 1:17', 'Ezekiel', 1, 17, 'ترڅو دا ارابې بې له تاوېدلو وکولای شي د څلورو خواو نه هرې خواته چې وغواړي حرکت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_17.mp3', '', 1761754199, 1761754199),
(51561, 'Ezekiel 1:18', 'Ezekiel', 1, 18, 'د ارابو څنډې لوړې او وېروونکې وې او ګردچاپېره په سترګو باندې پوښل شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_18.mp3', '', 1761754199, 1761754199),
(51562, 'Ezekiel 1:19', 'Ezekiel', 1, 19, 'کله به چې دې مخلوقاتو حرکت کاوه، نو ارابې به هم ورسره تللې او کله به چې دا مخلوقات د ځمکې څخه راپورته شول، نو ارابې به هم ورسره راپورته کېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_19.mp3', '', 1761754199, 1761754199),
(51563, 'Ezekiel 1:20', 'Ezekiel', 1, 20, 'هر‌چېرته به چې دې مخلوقاتو غوښتل هلته به تلل، نو ارابې به هم ورسره پورته کېدلې، ځکه چې دا ارابې د مخلوقاتو په واک کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_20.mp3', '', 1761754199, 1761754199),
(51564, 'Ezekiel 1:21', 'Ezekiel', 1, 21, 'کله به چې هغه مخلوقات تلل، نو ارابې به هم تللې او کله به چې هغه مخلوقات ودرېدل، نو ارابې به هم ودرېدلې. کله به چې هغه مخلوقات پورته تلل، نو ارابې به هم ورسره پورته کېدلې، ځکه چې دا ارابې د مخلوقاتو په واک کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_21.mp3', '', 1761754199, 1761754199),
(51565, 'Ezekiel 1:22', 'Ezekiel', 1, 22, 'د دې ژوندیو مخلوقاتو د سرونو دپاسه د میدان په شان یو ځای ؤ. دغه ځای د وېروونکي او ځلېدونکي یخ په شکل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_22.mp3', '', 1761754199, 1761754199),
(51566, 'Ezekiel 1:23', 'Ezekiel', 1, 23, 'د دې ځای لاندې د هر یو ژوندي مخلوق دوه وزرونه داسې خپاره شوي وو چې د هغه بل مخلوق وزرونو ته چې په څنګ کې یې ؤ، رسېدل او دوه نورو وزرونو د هغوی بدنونه پټول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_23.mp3', '', 1761754199, 1761754199),
(51567, 'Ezekiel 1:24', 'Ezekiel', 1, 24, 'ما هغه شورماشور چې د هغوی وزرونو د الوتلو په وخت کې جوړ کړی ؤ، واورېد چې د سیند د تېزو اوبو د غړمبېدلو په شان ؤ او د مطلق قادر خدای د اواز او د یو لوی لښکر د شورماشور په شان ؤ. کله به چې هغوی نه الوتل، نو خپل وزرونه به یې راټولول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_24.mp3', '', 1761754199, 1761754199),
(51568, 'Ezekiel 1:25', 'Ezekiel', 1, 25, 'اواز د هغه میدان د پاس نه راتله چې د دوی د سر دپاسه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_25.mp3', '', 1761754199, 1761754199),
(51569, 'Ezekiel 1:26', 'Ezekiel', 1, 26, 'د میدان دپاسه یو شی ؤ چې د داسې تخت په شان ؤ چې د لاجوردو څخه جوړ شوی ؤ او په تخت باندې یو داسې شکل ؤ چې د انسان په شان ښکاره کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_26.mp3', '', 1761754199, 1761754199),
(51570, 'Ezekiel 1:27', 'Ezekiel', 1, 27, 'د ملا څخه پورته هغه داسې ځلېده لکه په سور داش کې چې برنج ځلیږي او د ملا نه ښکته لکه د اور د لمبو په شان ښکاره کېده. د دې شکل شاوخوا یوې ځلېدونکې رڼا نیولې وه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_27.mp3', '', 1761754199, 1761754199),
(51571, 'Ezekiel 1:28', 'Ezekiel', 1, 28, 'لکه د بوډۍ د ټال په شان چې په یوې باراني ورځ کې وي. دا یوه ځلېدونکې رڼا وه او دا د څښتن د جلال د حضور څرګندوونکې وه. کله چې ما دا رویا ولیدله، نو په ځمکه باندې پړمخې پرېوتلم. بیا مې یو اواز واورېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel1_verse_28.mp3', '', 1761754199, 1761754199),
(51572, 'Ecclesiastes 3:1', 'Ecclesiastes', 3, 1, 'په نړۍ کې د هر شي دپاره وخت ټاکل شوی دی او هر مقصد په خپلې موقعې تر‌سره کیږي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_1.mp3', '', 1761754199, 1761754199),
(51573, 'Ecclesiastes 3:2', 'Ecclesiastes', 3, 2, 'د زېږېدلو دپاره وخت او د مړ کېدلو دپاره وخت د تخم کرلو دپاره وخت او له بېخه ویستلو دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_2.mp3', '', 1761754199, 1761754199),
(51574, 'Ecclesiastes 3:3', 'Ecclesiastes', 3, 3, 'د وژلو دپاره وخت او د روغولو دپاره وخت د ورانولو دپاره وخت او د ودانولو دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_3.mp3', '', 1761754199, 1761754199),
(51575, 'Ecclesiastes 3:4', 'Ecclesiastes', 3, 4, 'د ژړلو دپاره وخت او د خندلو دپاره وخت د ویر دپاره وخت او د ګډا دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_4.mp3', '', 1761754199, 1761754199),
(51576, 'Ecclesiastes 3:5', 'Ecclesiastes', 3, 5, 'د کاڼو غورځولو دپاره وخت او د کاڼو ټولولو دپاره وخت د غېږ ورکولو دپاره وخت او د غېږ نه ورکولو دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_5.mp3', '', 1761754199, 1761754199),
(51577, 'Ecclesiastes 3:6', 'Ecclesiastes', 3, 6, 'د لاسته راوړلو دپاره وخت او د لاسه ورکولو دپاره وخت د ځان سره ساتلو دپاره وخت او د ځان نه د جدا کولو دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_6.mp3', '', 1761754199, 1761754199),
(51578, 'Ecclesiastes 3:7', 'Ecclesiastes', 3, 7, 'د شلولو دپاره وخت او د ګنډلو دپاره وخت د چوپېدلو دپاره وخت او د غږېدلو دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_7.mp3', '', 1761754199, 1761754199),
(51579, 'Ecclesiastes 3:8', 'Ecclesiastes', 3, 8, 'د محبت دپاره وخت او د نفرت دپاره وخت د جګړې دپاره وخت او د سولې دپاره وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_8.mp3', '', 1761754199, 1761754199),
(51580, 'Ecclesiastes 3:9', 'Ecclesiastes', 3, 9, 'یو مزدور له خپل زیار او زحمت نه څه ګټه اخلي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_9.mp3', '', 1761754199, 1761754199),
(51581, 'Ecclesiastes 3:10', 'Ecclesiastes', 3, 10, 'ما د سختو کارونو دروند بار لیدلی چې خدای د انسانانو په اوږو ایښی دی چې پرې بوخت وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_10.mp3', '', 1761754199, 1761754199),
(51582, 'Ecclesiastes 3:11', 'Ecclesiastes', 3, 11, 'خدای هرڅه په خپل وخت په سمه او مناسبه توګه ټاکلي دي. د دې تر‌څنګ هغه د انسان په زړه کې د ابدیت پېژندنې ته هم ځای ورکړی دی. خو بیاهم انسان دا وس نه لري چې د خدای په کارونو چې له ازله تر ابده پورې یې تر‌سره کوي، پوه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_11.mp3', '', 1761754199, 1761754199),
(51583, 'Ecclesiastes 3:12', 'Ecclesiastes', 3, 12, 'نو زه دې نتیجې ته ورسېدم چې انسان باید له دې نعمتونو څخه چې خدای ورته ورکړي دي تر‌هغې پورې چې ژوندی دی، خوشحاله اوسي او ښه ژوند وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_12.mp3', '', 1761754199, 1761754199),
(51584, 'Ecclesiastes 3:13', 'Ecclesiastes', 3, 13, 'همدا شان انسان باید وخوري، وڅښي او د خپلو ټولو له زیار او زحمت نه ډکو کارونو نه خوند واخلي، ځکه چې دا د خدای نعمتونه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_13.mp3', '', 1761754199, 1761754199),
(51585, 'Ecclesiastes 3:14', 'Ecclesiastes', 3, 14, 'نو زه دې نتیجې ته ورسېدم چې هرڅه چې خدای تر‌سره کړي دي هغه تر ابده دوام مومي نه په هغه کې څه زیاتېدلی شي او نه هم څه کمېدلی شي خدای دا ټول په دې خاطر کړي دي چې خلک له هغه نه ووېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_14.mp3', '', 1761754199, 1761754199),
(51586, 'Ecclesiastes 3:15', 'Ecclesiastes', 3, 15, 'هرڅه چې اوس موجود دي هغه پخوا هم موجود وو او څه چې به وروسته موجود وي هغه هم پخوا موجود وو ځکه خدای غواړي چې پټ شیان بیا ښکاره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_15.mp3', '', 1761754199, 1761754199),
(51587, 'Ecclesiastes 3:16', 'Ecclesiastes', 3, 16, 'نو همدا شان ما د اسمان لاندې دا هم ولیدل: چېرته چې باید قضاوت وای هلته بدکاري وه او چېرته چې باید انصاف وای هلته هم بدکاري وه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_16.mp3', '', 1761754199, 1761754199),
(51588, 'Ecclesiastes 3:17', 'Ecclesiastes', 3, 17, 'له ځان سره مې وویل: «خدای به د نېکانو او بدکارانو په هکله قضاوت کوي. ځکه د هر مقصد او هر کار د قضاوت دپاره مناسب وخت ټاکل شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_17.mp3', '', 1761754199, 1761754199),
(51589, 'Ecclesiastes 3:18', 'Ecclesiastes', 3, 18, 'بیا مې له ځان سره وویل: «خدای د انسانانو ازمېښت کوي، ترڅو په خپله وګوري چې هغوی د ځناورو نه ښه‌والی نه لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_18.mp3', '', 1761754199, 1761754199),
(51590, 'Ecclesiastes 3:19', 'Ecclesiastes', 3, 19, 'ځکه چې د انسانانو او د ځناورو پای یو دی. هغه څه چې په یو پېښیږي په بل هم پېښیږي. یعنې انسانان هم مري او ځناور هم مري. نو دواړه د ژوندون یو ډول ساه لري او انسان له ځناورو نه هېڅ ښه‌والی نه لري، نو دا هرڅه لوګي او پوکي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_19.mp3', '', 1761754199, 1761754199),
(51591, 'Ecclesiastes 3:20', 'Ecclesiastes', 3, 20, 'دواړه یو ځای ته ځي دواړه له خاورو نه جوړ شوي دي او دواړه بېرته خاورو ته ځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_20.mp3', '', 1761754199, 1761754199),
(51592, 'Ecclesiastes 3:21', 'Ecclesiastes', 3, 21, 'څوک پوهیږي چې له مرګ څخه وروسته د انسانانو د ژوندون روح پورته او د ځناورو د ژوندون روح لاندې ځمکې ته ځي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_21.mp3', '', 1761754199, 1761754199),
(51593, 'Ecclesiastes 3:22', 'Ecclesiastes', 3, 22, 'نو ماته معلومه شوه چې تر ټولو ښه به دا وي چې انسان په خپل کار کې خوشحاله اوسي، ځکه دا د هغه برخه ده. نو څوک کولای شي چې انسان ته وښایي چې د هغه راتلونکی به څه ډول وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes3_verse_22.mp3', '', 1761754199, 1761754199),
(51594, 'Jeremiah 50:1', 'Jeremiah', 50, 1, 'مالِک خُدائ يرمياه نبى ته د بابل د خلقو او د بابل د وطن په حقله دا پېغام نازل کړو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_1.mp3', '', 1761754199, 1761754199),
(51595, 'Jeremiah 50:2', 'Jeremiah', 50, 2, '”د قومونو په مينځ کښې د دې خبرې اعلان وکړه، جنډا اوچته کړه او په ډاګه ورته ووايه، او هيڅ خبره مۀ پټوه بلکې دا ښکاره وايه چې، بابل به قبضه کړے شى، او بيل بُت به په شرمونو وشرميږى او رسوا به شى، او مردوک بُت به ويريږى. د بابل مجسمه به په شرمونو وشرمولے شى او د هغې بُتان يرې راخستى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_2.mp3', '', 1761754199, 1761754199),
(51596, 'Jeremiah 50:3', 'Jeremiah', 50, 3, 'د شمال د خوا نه به يو قوم په دې حمله وکړى او د هغوئ مُلک به تباه کړى او په صحرا به يې بدل کړى. او هيڅ څوک به هلته نۀ اوسيږى، انسانان او ځناور به وتښتى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_3.mp3', '', 1761754199, 1761754199),
(51597, 'Jeremiah 50:4', 'Jeremiah', 50, 4, 'مالِک خُدائ فرمائى چې، ”په هغه ورځو کښې به د اِسرائيل او د يهوداه خلق په يو ځائ په ژړا راروان وى. د مالِک خُدائ او د خپل مقدس خُدائ لټون به کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_4.mp3', '', 1761754199, 1761754199),
(51598, 'Jeremiah 50:5', 'Jeremiah', 50, 5, 'هغوئ به د صيون د لارې تپوس وکړى او بيا به هغه خوا ته مخ تاو کړى او ورروان به شى. هغوئ به ما سره ابدى لوظ وکړى کوم به چې کله هم نۀ هېريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_5.mp3', '', 1761754199, 1761754199),
(51599, 'Jeremiah 50:6', 'Jeremiah', 50, 6, 'زما غوره شوے قوم د ورکو شوو ګډو په شان دے، د هغوئ د قوم شپونکو هغه په غلطو لارو روان کړى دى او په غرونو کښې يې سرګردانه پرېښودى دى. او هغوئ په غرونو او غونډو سرګردانه ګرځى او خپل د آرام کولو ځائ ترې نه هېر وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_6.mp3', '', 1761754199, 1761754199),
(51600, 'Jeremiah 50:7', 'Jeremiah', 50, 7, 'هر چا به چې هم هغوئ بياموندل نو هغوئ به يې وژل. د هغوئ دشمنانو وئيل، مونږ په دوئ باندې په حملې کولو سره ګناه ګار نۀ يُو، ځکه چې هغوئ د مالِک خُدائ خلاف ګناه کړې ده څوک چې رښتينے څرن ځائ دے او د هغوئ پلار نيکۀ به هم په هغۀ باندې يقين او خپل اُميد ساتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_7.mp3', '', 1761754199, 1761754199),
(51601, 'Jeremiah 50:8', 'Jeremiah', 50, 8, 'اے زما غوره شوے قومه د بابل نه وتښتئ، د بابليانو مُلک پرېږدئ، او د هغه نر چېلى په شان شئ چې د رَمې رهنمائى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_8.mp3', '', 1761754199, 1761754199),
(51602, 'Jeremiah 50:9', 'Jeremiah', 50, 9, 'زۀ به د شمال نه د تکړه قومونو اِتحاد جوړ کړم او د بابل خلاف به يې راپاڅوم. او هغوئ به د بابل خلاف د جنګ دپاره صف بندى وکړى او د شمال د خوا نه به هغه قبضه کړى. او هغوئ په غشو ويشتو کښې ماهران دى چې کله هم د هغوئ غشى نۀ خطا کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_9.mp3', '', 1761754199, 1761754199),
(51603, 'Jeremiah 50:10', 'Jeremiah', 50, 10, 'خو بابل به لوټ کړے شى او هر هغه څوک چې هغه لوټ کړى او هر څۀ چې غواړى هغه به يوسى او ځان به پرې موړ کړى. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_10.mp3', '', 1761754199, 1761754199),
(51604, 'Jeremiah 50:11', 'Jeremiah', 50, 11, '”اے بابليانو تاسو چا چې زما غوره شوے قوم تالا والا کړو، او اوس په خپلو کښې خندا خوشحالى کوئ، تاسو د هغه سخى په شان ټوپونه وهئ کله چې هغه د موږى نه آزاد شى او د آس په شان هڼېږئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_11.mp3', '', 1761754199, 1761754199),
(51605, 'Jeremiah 50:12', 'Jeremiah', 50, 12, 'خو ستاسو خپله مور به رسوا شى، چا چې تاسو زيږولى يئ هغه به شرمنده شى. هغه به په ټولو مُلکونو کښې بې‌اهميته وى، هغه به په دشتو، په اوچه زمکه، او په صحرا بدله شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_12.mp3', '', 1761754199, 1761754199),
(51606, 'Jeremiah 50:13', 'Jeremiah', 50, 13, 'د مالِک خُدائ د غضب په وجه به بيا په کښې څوک نۀ اوسيږى خو بلکل به وران ويجاړ شى. څوک هم چې پرې تېريږى او د بابل تباهى وګورى نو د وحشت نه به حق حېران شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_13.mp3', '', 1761754199, 1761754199),
(51607, 'Jeremiah 50:14', 'Jeremiah', 50, 14, 'اے ليندو والاو تاسو ټولو چا چې خپلې ليندې راښکلى دى، د بابليانو خلاف د جنګ دپاره صف بندى وکړئ. په هغوئ باندې ګزار وکړئ. چې يو غشے درنه خطا نۀ شى. ځکه چې هغوئ د مالِک خُدائ خلاف ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_14.mp3', '', 1761754199, 1761754199),
(51608, 'Jeremiah 50:15', 'Jeremiah', 50, 15, 'د هرې خوا نه د هغۀ خلاف د جنګ چغې ووهئ. وګورئ هغه محاصره شوے دے، د هغۀ دېوالونه راغورزېدلى دى. دا د مالِک خُدائ د انتقام اخستو ورځ ده، د بابل نه انتقام واخلئ. کوم سلوک چې هغوئ د نورو سره کړے وو هم هغه شان سلوک ورسره وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_15.mp3', '', 1761754199, 1761754199),
(51609, 'Jeremiah 50:16', 'Jeremiah', 50, 16, 'د بابل خلق په پټو کښې د تخم کَرلو او فصل رېبلو نه منع کړئ، د ظالمانو د ظلم د وجې نه دې ټول غېر مُلکيان خپلو خلقو او خپل مُلک ته واپس لاړ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_16.mp3', '', 1761754199, 1761754199),
(51610, 'Jeremiah 50:17', 'Jeremiah', 50, 17, '”بنى اِسرائيل د ګډو د هغه خورې ورې شوې رمې په شان دے چې زمرو په مخه کړې وى. په اول ځل چې چا تېر کړل هغه د اسور بادشاه وو، په آخر کښې چا چې د هغۀ هډُوکى مات کړل هغه نبوکدنضر د بابل بادشاه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_17.mp3', '', 1761754199, 1761754199);